// Generated by Manus asset storage.
import { restoreThreejsAssets, assetRestoreDiagnostic } from './threejs-asset-restore.mjs'
import { referencedLocalAssets } from './threejs-asset-inputs.mjs'
import { cpSync, existsSync, mkdirSync } from 'node:fs'
import { join } from 'node:path'

const root = process.cwd()

try {
  const inputs = await referencedLocalAssets(root)
  await restoreThreejsAssets(root, { includeAsset: rel => inputs.has(rel) })
} catch (error) {
  console.warn('Asset restore notice (continuing with local assets):', error?.message || error)
}

// Ensure static assets are mirrored to public/assets so Vite packages them for static hosts (GitHub Pages, Vercel, Netlify)
try {
  const src = join(root, 'assets')
  const dest = join(root, 'public', 'assets')
  if (existsSync(src)) {
    mkdirSync(dest, { recursive: true })
    cpSync(src, dest, { recursive: true, force: true })
  }
} catch (copyErr) {
  console.warn('Could not mirror assets to public/assets:', copyErr)
}


